// factory-loop-workspace: the factory loop's companion plugin (docs/factory-loop/v2/SPEC.md 10.3 to
// 10.6, 10.9). The engine never runs a plugin's hooks for what that plugin's own code started, and
// the loop starts its agents from its timer, so its own hooks never see them (SPIKES.md). This
// second plugin's hooks do, and carry what the loop needs around each agent it starts:
//
// - the folder (10.3): a spawn whose prompt opens with `factory-slot: <path>` is started in that
//   slot, once the slot's step marker matches the spawn; a missing or mismatched marker refuses it;
// - the map: the agent's id, and its children's, to its slot and marker, kept in $.state;
// - the write guard (10.4): file writes and commands the agent's role may not make are refused,
//   each refusal appended to <loop dir>/companion.jsonl, which the loop logs as an intervention;
// - the timeout (10.5): a Bash call with no timeout gets 10 minutes;
// - the stop gate (10.6): a writer may not finish while the repo's gate commands fail; a gate that
//   cannot run lets it finish, logged as gate-unknown; every run is a line of companion.jsonl, the
//   last also in factory-gate.json;
// - prompts nobody answers (10.10): a call of a mapped agent that Claude Code would put to a person
//   (tool.check answered `ask`) is denied instead, with a reason that tells the agent to find another
//   way, and written as a `prompt_denied` event and a `prompt-denied` line of companion.jsonl; a
//   permission_prompt notification of a mapped agent is a `prompt_waiting` event. A caller that is
//   not in the map (the owner's own session) is never touched;
// - the handshake (10.9): <CLAUDE_CONFIG_DIR>/factory-loop/workspace/<session>.json says this
//   session has the companion, and in which process, written again every minute; the loop holds
//   every agent step while its own is missing, from another process or stale.
//
// It acts only on spawns that carry the slot line, so the loop's v1 agents and every other agent
// pass untouched.
import type { EngineInterface, Register } from 'claude-code'
import type { WorkspaceAgent } from '../types'
import { blockText, gateLine, gateRecord, oneLine, runGates, waitedOut } from './gate'
import type { Ran } from './gate'
import { FILE_TOOLS, agentRefusal, backgroundRefusal, bashRefusal, fileRefusal, needsHead, normalize, within } from './guard'
import type { Guarded, Refusal } from './guard'
import { MARKER_FILE, mismatch, nameParts, parseMarker, slotLine } from './marker'
import { PROMPT_NOTIFICATIONS, inputOf, promptNote, promptReason, transcriptOf, whyOf } from './prompt'
import type { Decided, NoteFields } from './prompt'
import { withScratch } from './scratch'
import { createTurns } from './turns'
import type { Turn } from './turns'

const ME = 'factory-loop-workspace'
const AGENTS = { plugin: 'factory-loop-workspace', key: 'agents' } as const
export const BASH_TIMEOUT_MS = 600_000
// the most a single $.process.run may take
const RUN_MAX_MS = 600_000
const QUICK_MS = 15_000
// the handshake is written again this often: its `at` shows the companion runs now, and the loop
// takes a handshake a few beats old as missing (factory-loop hooks/v2/sources-workspace.ts)
export const HANDSHAKE_EVERY_MS = 60_000
const HANDSHAKE_PRUNE_DAYS = 7
// the longest a finished writer waits for its gate's turn when its marker does not say (config.ts
// gateWaitTimeoutMs)
const GATE_WAIT_TIMEOUT_MS = 30 * 60_000
// the stop gates' turns, one set for the whole process: every slot's writer shares it
const turns = createTurns()

// --- small helpers over $ ---------------------------------------------------------------------------

async function run($: EngineInterface, argv: string[], opts: { cwd?: string; stdin?: string; timeoutMs?: number } = {}) {
  return $.process.run(argv, { timeoutMs: QUICK_MS, ...opts })
}

async function readText($: EngineInterface, path: string): Promise<string | null> {
  try {
    return await $.fs.read(path)
  } catch {
    return null
  }
}

// writeFile: written whole by rename, its folder made first.
async function writeFile($: EngineInterface, path: string, text: string): Promise<void> {
  const r = await run($, ['sh', '-c', 'mkdir -p "$(dirname "$1")" && cat > "$1.tmp.$$" && mv -f "$1.tmp.$$" "$1"', 'sh', path], { stdin: text })
  if (r.exitCode !== 0) throw new Error(`${path}: ${oneLine(r.stderr)}`)
}

async function appendFile($: EngineInterface, path: string, text: string): Promise<void> {
  const r = await run($, ['sh', '-c', 'mkdir -p "$(dirname "$1")" && cat >> "$1"', 'sh', path], { stdin: text })
  if (r.exitCode !== 0) throw new Error(`${path}: ${oneLine(r.stderr)}`)
}

// configDir: CLAUDE_CONFIG_DIR, else ~/.claude, as the loop builds its own paths.
async function configDir($: EngineInterface): Promise<string> {
  const dir = (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) || '~'}/.claude`
  return dir.replace(/\/{2,}/g, '/').replace(/(.)\/$/, '$1')
}

// --- the handshake (10.9) ---------------------------------------------------------------------------

// handshakePath: one file per session, so two sessions with the companion never write one file.
export function handshakePath(configDir: string, session: string): string {
  return `${configDir}/factory-loop/workspace/${session.replace(/[^A-Za-z0-9._-]/g, '_')}.json`
}

// processIdOf: the process that /proc/<pid>/stat describes, by its pid and start time, which no
// other process has: not a child, which has its own, and not a later one given the same pid. Its
// field 22 is counted after the command name, which may hold spaces. undefined: no stat to read.
export function processIdOf(stat: string | null): string | undefined {
  const pid = stat?.split(' ', 1)[0] ?? ''
  const start = stat?.slice(stat.lastIndexOf(') ') + 2).split(' ')[19] ?? ''
  return /^\d+$/.test(pid) && /^\d+$/.test(start) ? `${pid}:${start}` : undefined
}

// handshake: this session's file, written whole with this process's id and the time now (no id:
// null, which the loop never takes).
async function handshake($: EngineInterface): Promise<void> {
  const session = await $.session.id()
  // this process, as the loop, a plugin of the same process, reads it too
  const proc = processIdOf(await readText($, '/proc/self/stat')) ?? null
  const now = await $.clock.now()
  const path = handshakePath(await configDir($), session)
  const manifest = await readText($, `${$.plugin.root}/.claude-plugin/plugin.json`)
  let version = 'unknown'
  try {
    const v = (JSON.parse(manifest ?? '{}') as { version?: unknown }).version
    if (typeof v === 'string') version = v
  } catch {
    // the version is for people reading the file; the loop reads the rest
  }
  await writeFile($, path, `${JSON.stringify({ v: 1, session, process: proc, version, at: new Date(now).toISOString() })}\n`)
}

let beat: { cancel: () => void } | null = null

// beating: the handshake now and again every minute, so its `at` stays fresh, a /clear's new
// session gets its own file, and a pruned or deleted one comes back.
async function beating($: EngineInterface): Promise<void> {
  beat?.cancel()
  beat = $.clock.every(HANDSHAKE_EVERY_MS, () => void handshake($).catch(() => undefined))
  await handshake($).catch(() => undefined)
}

async function pruneHandshakes($: EngineInterface): Promise<void> {
  const dir = `${await configDir($)}/factory-loop/workspace`
  await run($, ['find', dir, '-maxdepth', '1', '-name', '*.json', '-mtime', `+${HANDSHAKE_PRUNE_DAYS}`, '-delete'])
}

// --- the map ----------------------------------------------------------------------------------------

async function agentOf($: EngineInterface, agentId: string): Promise<WorkspaceAgent | null> {
  const { value } = await $.state.get({ ...AGENTS, id: agentId })
  return value ?? null
}

async function keep($: EngineInterface, agentId: string, agent: WorkspaceAgent): Promise<void> {
  await $.state.set({ ...AGENTS, id: agentId }, agent)
}

// --- the slot (10.3) --------------------------------------------------------------------------------

// placeOf: the slot's git dir, real path and repository roots, or why it is no slot.
async function placeOf($: EngineInterface, slot: string): Promise<{ gitDir: string; real: string; roots: string[] } | { deny: string }> {
  let real: string
  try {
    const st = await $.fs.stat(slot, { resolve: true })
    if (st.kind !== 'dir') return { deny: `${slot} is not a folder` }
    real = st.realPath ?? slot
  } catch {
    return { deny: `${slot} does not exist` }
  }
  const r = await run($, ['git', '-C', slot, 'rev-parse', '--path-format=absolute', '--show-toplevel', '--absolute-git-dir', '--git-common-dir'])
  const [top, gitDir, common] = r.stdout.trim().split('\n')
  if (r.exitCode !== 0 || gitDir === undefined || common === undefined) return { deny: `${slot} is not a git checkout: ${oneLine(r.stderr)}` }
  if (top !== real && top !== slot) return { deny: `${slot} is not the top of its checkout (${top})` }
  const roots = [...new Set([slot, real, ...(common.endsWith('/.git') ? [common.slice(0, -'/.git'.length)] : [])])]
  return { gitDir, real, roots }
}

// --- the guard (10.4) -------------------------------------------------------------------------------

function guardedOf(a: WorkspaceAgent): Guarded {
  return { slot: a.slot, role: a.role, branch: a.branch, roots: a.roots }
}

// placed: a path's real location, symlinks resolved through its nearest existing folder; null when
// none can be read.
async function placed($: EngineInterface, path: string): Promise<string | null> {
  let rest = ''
  let at = path
  for (let i = 0; i < 64 && at !== ''; i++) {
    const st = await $.fs.stat(at, { resolve: true }).catch(() => null)
    if (st !== null && st.realPath !== undefined) return normalize(`${st.realPath}${rest}`, '/')
    const cut = at.lastIndexOf('/')
    rest = `${at.slice(cut)}${rest}`
    at = at.slice(0, cut)
  }
  return null
}

async function headBranch($: EngineInterface, slot: string): Promise<string | null> {
  const r = await run($, ['git', '-C', slot, 'symbolic-ref', '--quiet', '--short', 'HEAD']).catch(() => null)
  return r !== null && r.exitCode === 0 ? r.stdout.trim() : null
}

async function refusalOf($: EngineInterface, a: WorkspaceAgent, e: Record<string, unknown>, tool: string): Promise<Refusal | null> {
  const g = guardedOf(a)
  const background = backgroundRefusal(tool, e)
  if (background !== null) return background
  if (tool === 'Agent') return agentRefusal(e)
  if ((FILE_TOOLS as readonly string[]).includes(tool)) {
    const raw = typeof e.file_path === 'string' ? e.file_path : typeof e.notebook_path === 'string' ? e.notebook_path : null
    if (raw === null) return null
    const path = normalize(raw, a.slot)
    const lexical = fileRefusal(g, path)
    if (lexical !== null) return lexical
    // a symlink must not carry a write out of the slot, or into the repository for a reader
    const real = await placed($, path)
    if (real === null || real === path) return null
    const refused = fileRefusal({ ...g, slot: within(path, a.slot) ? a.real : g.slot }, real)
    return refused === null ? null : { ...refused, reason: `${raw} resolves to ${real}: ${refused.reason}` }
  }
  if (tool === 'Bash' && typeof e.command === 'string') {
    const head = needsHead(e.command) ? await headBranch($, a.slot) : null
    return bashRefusal(g, e.command, head)
  }
  return null
}

// logLine: one line of the companion's log, which the loop reads (v2/sources-interventions.ts).
async function logLine($: EngineInterface, a: WorkspaceAgent, cause: string, reason: string, fields: Record<string, unknown> = {}): Promise<void> {
  const line = { at: new Date(await $.clock.now()).toISOString(), issue: a.issue, life: a.life, seq: a.seq, cause, reason: oneLine(reason, 500), ...fields }
  await appendFile($, `${a.loopDir}/companion.jsonl`, `${JSON.stringify(line)}\n`).catch(() => undefined)
}

// --- prompts nobody answers (10.10) -----------------------------------------------------------------

// the transcripts SubagentStart reported before the agent was in the map, by agent id (the newest
// 200); the map's own record has it once it is
const transcripts = new Map<string, string>()
const TRANSCRIPTS_KEPT = 200

function transcriptSeen(agentId: string, a: WorkspaceAgent): string | null {
  return a.transcript ?? transcripts.get(agentId) ?? null
}

// eventLine: one factory event through `callum-flow-event`, in the issue's repository. A failure
// (an image that does not know the state exits 2, a missing command) is swallowed: the caller has
// already done what it must.
async function eventLine($: EngineInterface, a: WorkspaceAgent, state: string, note: string): Promise<void> {
  const argv = ['callum-flow-event', state, '--issue', String(a.issue), '--branch', a.branch, ...(typeof a.pr === 'number' ? ['--pr', String(a.pr)] : []), '--repo', a.repo, '--note', note]
  await run($, argv, { cwd: a.slot }).catch(() => undefined)
}

// promptFields: the note's tokens for this agent; what cannot be read is none.
async function promptFields($: EngineInterface, a: WorkspaceAgent, agentId: string): Promise<NoteFields> {
  const session = await $.session.id().catch(() => null)
  return {
    life: a.life,
    seq: a.seq,
    step: a.step,
    attempt: a.attempt,
    agent: agentId,
    agent_type: a.agentType,
    slot: a.slot,
    session,
    transcript: transcriptSeen(agentId, a),
  }
}

// refusePrompt: the deny for a mapped agent's call that Claude Code answered `ask`, with its event
// and its line. Whatever of those fails, the deny stands.
async function refusePrompt($: EngineInterface, a: WorkspaceAgent, e: { tool: string; input?: unknown; agentId?: string }, decided: Decided): Promise<{ decision: 'deny'; reason: string }> {
  const reason = promptReason(e.tool, e.input, decided)
  try {
    const note = promptNote({ ...(await promptFields($, a, e.agentId ?? '')), tool: e.tool, why: whyOf(decided), input: inputOf(e.tool, e.input) })
    await eventLine($, a, 'prompt_denied', note)
  } catch {
    // the deny is what matters
  }
  await logLine($, a, 'prompt-denied', `${e.tool}: ${reason}`).catch(() => undefined)
  return { decision: 'deny', reason }
}

// --- the stop gate (10.6) ---------------------------------------------------------------------------

async function runIn($: EngineInterface, slot: string, command: string, budgetMs: number): Promise<Ran> {
  try {
    const r = await $.process.run(['sh', '-c', `exec 2>&1\n${command}`], { cwd: slot, timeoutMs: Math.min(budgetMs, RUN_MAX_MS) })
    return { exitCode: r.exitCode, output: r.stdout }
  } catch (err) {
    return { error: err instanceof Error ? err.message : String(err) }
  }
}

async function headSha($: EngineInterface, slot: string): Promise<string | null> {
  const r = await run($, ['git', '-C', slot, 'rev-parse', 'HEAD']).catch(() => null)
  return r !== null && r.exitCode === 0 ? r.stdout.trim() : null
}

// --- the hooks --------------------------------------------------------------------------------------

export const register: Register = on => {

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await beating($)
    await pruneHandshakes($).catch(() => undefined)
    return r
  })

  // session.start does not fire for a plugin a /reload-plugins adds to a running session: the
  // first row or turn after such a load starts the beat instead
  on('session.append', async ($, e, next) => {
    if (beat === null) void beating($).catch(() => undefined)
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.start', async ($, e, next) => {
    if (beat === null) void beating($).catch(() => undefined)
    return next(e)
  }).catch(($, e, next) => next(e))

  on('agent.spawn', async ($, e, next) => {
    // a child of an agent in a slot: the same slot and rules, and its folder is inherited
    if (e.parentAgentId !== undefined) {
      const parent = await agentOf($, e.parentAgentId)
      if (parent !== null) {
        const r = await next(e)
        // its own type; its transcript is its own too, learned when it starts
        const { transcript: _t, ...inherited } = parent
        if (r.agentId !== undefined) await keep($, r.agentId, { ...inherited, agentType: e.subagentType })
        return r
      }
    }
    const slot = slotLine(e.prompt)
    if (slot === null) return next(e)
    const place = await placeOf($, slot)
    if ('deny' in place) return { deny: `${ME}: ${place.deny}` }
    const marker = parseMarker(await readText($, `${place.gitDir}/${MARKER_FILE}`))
    const why = mismatch(marker, e)
    if (why !== null || marker === null) return { deny: `${ME}: ${why ?? 'no marker'}` }
    const r = await next({ ...e, cwd: slot })
    if (r.agentId !== undefined) {
      const { v: _v, ...fields } = marker
      const attempt = nameParts(e.name)?.attempt
      await keep($, r.agentId, { ...fields, root: r.agentId, slot, real: place.real, roots: place.roots, gitDir: place.gitDir, agentType: e.subagentType, ...(attempt === undefined ? {} : { attempt }) })
    }
    return r
  }).catch(($, e, next) => (next.called ? next(e) : slotLine(e.prompt) !== null ? { deny: `${ME}: its spawn hook failed, so the agent was not started outside its slot` } : next(e)))

  on('tool.call', async ($, e, next) => {
    if (e.agentId === undefined) return next(e)
    const a = await agentOf($, e.agentId)
    if (a === null) return next(e)
    const input = e as unknown as Record<string, unknown>
    const refused = await refusalOf($, a, input, e.tool)
    if (refused !== null) {
      await logLine($, a, refused.cause, `${e.tool}: ${refused.reason}`)
      return { deny: `${ME}: ${refused.reason}` }
    }
    if (e.tool === 'Bash') {
      // the guard judged the agent's own command; what runs has the scratch folder exported first
      const command = a.scratch !== undefined && typeof input.command === 'string' ? withScratch(input.command, a.scratch) : undefined
      if (command !== undefined || e.timeout === undefined) {
        return next({ ...input, ...(command === undefined ? {} : { command }), ...(e.timeout === undefined ? { timeout: BASH_TIMEOUT_MS } : {}) } as unknown as typeof e)
      }
    }
    return next(e)
  }).catch(($, e, next) => (next.called || e.agentId === undefined ? next(e) : { deny: `${ME}: its guard failed, so the call is refused` }))

  // the call Claude Code would ask a person about: a mapped agent has nobody to ask
  on('tool.check', async ($, e, next) => {
    const r = await next(e)
    if (r.decision !== 'ask' || e.agentId === undefined) return r
    const a = await agentOf($, e.agentId)
    if (a === null) return r
    return refusePrompt($, a, e, r)
  }).catch(async ($, e, next) => {
    // a failure after `ask` came back, for a mapped agent, is still a deny
    const r = await next(e)
    if (r.decision !== 'ask' || e.agentId === undefined) return r
    const a = await agentOf($, e.agentId).catch(() => null)
    return a === null ? r : { decision: 'deny', reason: promptReason(e.tool, e.input, r) }
  })

  // a subagent's transcript is beside the session's: the hook's transcript_path is the session's
  on('classic.SubagentStart', async ($, e, next) => {
    const transcript = transcriptOf((e as { transcript_path?: unknown }).transcript_path, e.agent_id)
    if (transcript !== null) {
      transcripts.delete(e.agent_id)
      transcripts.set(e.agent_id, transcript)
      for (const old of [...transcripts.keys()].slice(0, Math.max(0, transcripts.size - TRANSCRIPTS_KEPT))) transcripts.delete(old)
      const a = await agentOf($, e.agent_id)
      if (a !== null) await keep($, e.agent_id, { ...a, transcript })
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  // a mapped agent's permission prompt, waiting: written, never answered
  on('classic.Notification', async ($, e, next) => {
    const agentId = (e as { agent_id?: unknown }).agent_id
    if (typeof agentId === 'string' && PROMPT_NOTIFICATIONS.includes(e.notification_type)) {
      const a = await agentOf($, agentId)
      if (a !== null) {
        const note = promptNote({ ...(await promptFields($, a, agentId)), input: e.message })
        await eventLine($, a, 'prompt_waiting', note)
      }
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('classic.SubagentStop', async ($, e, next) => {
    const a = await agentOf($, e.agent_id)
    if (a === null || a.root !== e.agent_id || a.role !== 'writer' || a.gateCommands.length === 0) return next(e)
    // a turn first (10.6): at most gateConcurrency gates run at once in this process; a marker with no
    // limit takes none
    const limit = a.gateConcurrency
    let turn: Extract<Turn, { ok: true }> | null = null
    let waitMs = 0
    let queuedBehind = 0
    // when the gate asked for its turn, before any wait, with or without a limit
    const startedAt = new Date(await $.clock.now()).toISOString()
    if (limit !== undefined) {
      const cap = a.gateWaitTimeoutMs ?? GATE_WAIT_TIMEOUT_MS
      const got = await turns.acquire(limit, { now: () => $.clock.now(), after: (ms, fn) => $.clock.after(ms, fn), maxWaitMs: cap })
      waitMs = got.waitMs
      queuedBehind = got.queuedBehind
      if (!got.ok) {
        const result = waitedOut(got.waitMs, cap, limit)
        const head = await headSha($, a.slot)
        await writeFile($, `${a.gitDir}/factory-gate.json`, `${JSON.stringify(gateRecord(result, head, await $.clock.now(), a.gateCommands, waitMs), null, 2)}\n`).catch(() => undefined)
        const line = gateLine(result, head, waitMs, limit, startedAt, queuedBehind)
        await logLine($, a, line.cause, line.reason, line.fields)
        return next(e)
      }
      turn = got
    }
    // whatever happens from here, the turn goes back, so a stuck or crashed gate never blocks the others
    try {
      if (turn !== null && turn.queuedBehind > 0) await logLine($, a, 'gate-wait', `the stop gate waited ${Math.round(waitMs / 1000)} s for a turn`, { waitMs, queuedBehind: turn.queuedBehind, concurrency: limit })
      const result = await runGates({ run: (command, budgetMs) => runIn($, a.slot, command, budgetMs), now: () => $.clock.now() }, a.gateCommands, a.gateTimeoutMs)
      const head = await headSha($, a.slot)
      const record = gateRecord(result, head, await $.clock.now(), a.gateCommands, waitMs)
      await writeFile($, `${a.gitDir}/factory-gate.json`, `${JSON.stringify(record, null, 2)}\n`).catch(() => undefined)
      const line = gateLine(result, head, waitMs, limit ?? null, startedAt, queuedBehind)
      await logLine($, a, line.cause, line.reason, line.fields)
      if (result.result === 'fail') return { block: blockText(result, a.slot, a.gateCommands) }
      return next(e)
    } finally {
      turn?.release()
    }
  }).catch(async ($, e, next) => {
    // a gate that could not run is never passed silently
    try {
      const a = await agentOf($, e.agent_id)
      if (a !== null && a.root === e.agent_id && a.role === 'writer' && a.gateCommands.length > 0) await logLine($, a, 'gate-unknown', 'the stop gate hook failed')
    } catch {
      // nothing more can be said
    }
    return next(e)
  })
}

files.hooks/gate.ts:
// The stop gate (docs/factory-loop/v2/SPEC.md 10.6): the repo's gate commands, run in the slot one
// after another as `a && b` would run them, inside one total budget. A failing command refuses the
// writer's finish with the command, its exit code and the last lines of its output; a gate that
// cannot run (its budget spent, or a command that could not start) lets the agent finish and is
// recorded as unknown, never as a pass. register.ts supplies how a command runs and the clock.

export const TAIL_LINES = 150

// One command's run: its exit code and its output (standard output then standard error), or the
// error that kept it from finishing (a timeout, a failure to start).
export type Ran = { exitCode: number; output: string } | { error: string }

export type GateResult =
  | { result: 'pass'; ms: number }
  | { result: 'fail'; ms: number; command: string; exitCode: number; tail: string }
  | { result: 'unknown'; ms: number; why: string }

export type GateIo = {
  // runs one command in the slot within budgetMs
  run: (command: string, budgetMs: number) => Promise<Ran>
  now: () => Promise<number>
}

// The least budget a command is started with; less than this left counts as the budget spent.
const MIN_BUDGET_MS = 1_000

// runGates: the commands in order, stopping at the first that fails or cannot run.
export async function runGates(io: GateIo, commands: readonly string[], budgetMs: number): Promise<GateResult> {
  const t0 = await io.now()
  const spent = async () => (await io.now()) - t0
  for (const command of commands) {
    const left = budgetMs - (await spent())
    if (left < MIN_BUDGET_MS) return { result: 'unknown', ms: await spent(), why: `the gate's budget of ${Math.round(budgetMs / 1000)} s ran out before \`${command}\`` }
    let ran: Ran
    try {
      ran = await io.run(command, left)
    } catch (err) {
      ran = { error: err instanceof Error ? err.message : String(err) }
    }
    if ('error' in ran) return { result: 'unknown', ms: await spent(), why: `\`${command}\` did not finish: ${oneLine(ran.error)}` }
    if (ran.exitCode !== 0) return { result: 'fail', ms: await spent(), command, exitCode: ran.exitCode, tail: tail(ran.output) }
  }
  return { result: 'pass', ms: await spent() }
}

// tail: the last TAIL_LINES lines of an output, without its trailing blank lines.
export function tail(output: string, lines = TAIL_LINES): string {
  const all = output.replace(/\s+$/, '').split('\n')
  return all.slice(-lines).join('\n')
}

export function oneLine(text: string, max = 300): string {
  const line = text.replace(/\s+/g, ' ').trim()
  return line.length > max ? `${line.slice(0, max - 3)}...` : line
}

// blockText: what the agent is told when the gate refuses its finish.
export function blockText(r: Extract<GateResult, { result: 'fail' }>, slot: string, commands: readonly string[]): string {
  return [
    `The stop gate failed in your slot ${slot}: \`${r.command}\` exited ${r.exitCode}. The gates are ${commands.map(c => `\`${c}\``).join(' then ')}; your step cannot finish while one fails.`,
    `Fix the failures, commit and push your branch, then finish again. The last ${TAIL_LINES} lines of its output:`,
    '```',
    r.tail,
    '```',
  ].join('\n')
}

// gateRecord: the result as factory-gate.json holds it in the slot's git dir, with the slot's HEAD
// (null: not read), for the decision log and the triage's inputs.
export function gateRecord(r: GateResult, head: string | null, at: number, commands: readonly string[], waitMs = 0): Record<string, unknown> {
  const base = { v: 1, at: new Date(at).toISOString(), head, commands: [...commands], result: r.result, ms: r.ms, waitMs }
  if (r.result === 'fail') return { ...base, command: r.command, exitCode: r.exitCode, tail: r.tail }
  if (r.result === 'unknown') return { ...base, why: r.why }
  return base
}

// gateLine: every run as one line of the companion's log, which outlives factory-gate.json (the
// next run overwrites it), so a step's gate runs can be audited. Only `gate-unknown` is an
// intervention (SPEC 7.2); the loop skips `gate-pass` and `gate-fail`, the gate doing its work.
// waitMs is the time the gate waited for its turn and concurrency the limit it ran under (null: none).
// startedAt (ISO, 3 ms digits) is when it asked for its turn, before any wait, and queuedBehind how
// many held a turn or waited ahead of it then (0: none); the loop writes `gate_run` from these.
export function gateLine(
  r: GateResult,
  head: string | null,
  waitMs: number,
  concurrency: number | null,
  startedAt: string,
  queuedBehind: number,
): { cause: string; reason: string; fields: Record<string, unknown> } {
  const fields = { head, ms: r.ms, waitMs, concurrency, startedAt, queuedBehind }
  if (r.result === 'pass') return { cause: 'gate-pass', reason: 'the stop gate passed', fields }
  if (r.result === 'fail') return { cause: 'gate-fail', reason: `the stop gate refused the finish: \`${r.command}\` exited ${r.exitCode}`, fields: { ...fields, command: r.command, exitCode: r.exitCode } }
  return { cause: 'gate-unknown', reason: `the stop gate could not run: ${r.why}`, fields }
}

// waitedOut: the result of a gate that never got a turn within the wait cap: unknown, never a pass.
export function waitedOut(waitMs: number, capMs: number, concurrency: number): GateResult {
  return { result: 'unknown', ms: 0, why: `it waited ${Math.round(waitMs / 1000)} s for a turn (the cap is ${Math.round(capMs / 1000)} s, ${concurrency} gate${concurrency === 1 ? '' : 's'} at once) and the gate never ran` }
}

files.hooks/guard.ts:
// The write guard's rules (docs/factory-loop/v2/SPEC.md 10.4), pure: what a loop agent may not
// do, by its role, with the reason the agent is told. register.ts applies them in its tool.call
// hook to the agents the loop started in a slot, and to their children.
//
// - File tools: a writer writes inside its slot or outside the repository (a scratch file in
//   the step's scratch folder); a reader writes nowhere in the repository. The repository is the slot and the main
//   checkout, whose tree holds the pool's other slots.
// - Every loop agent: no GitHub writes (the loop owns PRs, issues, labels and re-runs), no
//   no-mistakes, no axi, no push to a remote but origin, no call in the background (Bash or
//   Agent), no isolated Agent call.
// - A writer pushes only its branch to origin, never by force, creates no branch and no worktree.
// - A reader neither commits nor pushes.
import { program, simpleCommands } from './shell'

export type Role = 'writer' | 'reader'

// What the guard knows of an agent: its slot, its role and branch (the step marker's), and the
// repository's roots (the slot, and the main checkout when the slot is one of its worktrees).
export type Guarded = { slot: string; role: Role; branch: string; roots: string[] }

export type Cause = 'guard:write' | 'guard:push' | 'guard:command'
export type Refusal = { cause: Cause; reason: string }

export const FILE_TOOLS = ['Edit', 'Write', 'MultiEdit', 'NotebookEdit'] as const

// --- paths ------------------------------------------------------------------------------------------

// normalize: an absolute path with no `.`, `..` or doubled `/`; a relative one is resolved
// against base first (Write's file_path can arrive relative).
export function normalize(path: string, base: string): string {
  const out: string[] = []
  for (const part of (path.startsWith('/') ? path : `${base}/${path}`).split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return `/${out.join('/')}`
}

export function within(path: string, root: string): boolean {
  return root === '/' || path === root || path.startsWith(`${root}/`)
}

// fileRefusal: a file tool's write to path (absolute, normalized), or null when it may go ahead.
export function fileRefusal(g: Guarded, path: string): Refusal | null {
  const inRepo = within(path, g.slot) || g.roots.some(r => within(path, r))
  if (g.role === 'writer') {
    if (within(path, g.slot) || !inRepo) return null
    return { cause: 'guard:write', reason: `${path} is outside your slot ${g.slot}: write only inside it` }
  }
  if (!inRepo) return null
  return { cause: 'guard:write', reason: `${path} is in the repository, and this step reads only: write nowhere in ${g.slot} or another checkout (a scratch file outside the repository is fine)` }
}

// --- commands ---------------------------------------------------------------------------------------

// The gh commands that write to GitHub, by group, aliases included (`gh pr new` is `gh pr
// create`): the loop owns these (10.4). `*`: every subcommand of the group.
const GH_WRITES: Record<string, readonly string[] | '*'> = {
  pr: ['create', 'new', 'edit', 'merge', 'close', 'reopen', 'review', 'update-branch', 'comment', 'ready', 'revert', 'lock', 'unlock'],
  issue: ['create', 'new', 'edit', 'close', 'comment', 'reopen', 'delete', 'transfer', 'lock', 'unlock', 'pin', 'unpin', 'develop'],
  label: '*',
  run: ['rerun', 'cancel', 'delete'],
  workflow: ['run', 'enable', 'disable'],
  release: ['create', 'new', 'edit', 'delete', 'upload', 'delete-asset'],
  repo: ['create', 'new', 'edit', 'rename', 'archive', 'unarchive', 'delete', 'sync', 'fork', 'deploy-key'],
  secret: '*',
  variable: '*',
  cache: ['delete'],
  gist: ['create', 'new', 'edit', 'rename', 'delete'],
}
const GH_VALUED = ['-R', '--repo', '-H', '--header', '-q', '--jq', '-t', '--template', '-p', '--preview', '--hostname', '--cache']
const WRITE_METHODS = ['POST', 'PUT', 'PATCH', 'DELETE']
const FIELD_FLAGS = ['-f', '-F', '--field', '--raw-field', '--input']
const LOOP_TOOLS = ['no-mistakes', 'axi']

// The git options that come before the subcommand and take a value.
const GIT_VALUED = ['-C', '-c', '--git-dir', '--work-tree', '--namespace', '--exec-path', '--config-env']

// gitArgs: a git command's subcommand and its arguments, past git's own options; null when argv
// runs no git subcommand.
function gitArgs(argv: readonly string[]): string[] | null {
  let i = 1
  while (i < argv.length && (argv[i] ?? '').startsWith('-')) i += GIT_VALUED.includes(argv[i] ?? '') ? 2 : 1
  return i < argv.length ? argv.slice(i) : null
}

function ghArgs(argv: readonly string[]): string[] {
  const out: string[] = []
  for (let i = 1; i < argv.length; i++) {
    const a = argv[i] ?? ''
    if (GH_VALUED.includes(a)) i++
    else if (!a.startsWith('-')) out.push(a)
  }
  return out
}

// ghWrite: why a gh command writes to GitHub, or null.
function ghWrite(argv: readonly string[]): string | null {
  const [group, sub] = ghArgs(argv)
  if (group === 'api') {
    let method: string | null = null
    let fields = false
    for (let i = 1; i < argv.length; i++) {
      const a = argv[i] ?? ''
      if (a === '-X' || a === '--method') method = (argv[i + 1] ?? '').toUpperCase()
      else if (/^-X./.test(a)) method = a.slice(2).toUpperCase()
      else if (a.startsWith('--method=')) method = a.slice('--method='.length).toUpperCase()
      else if (FIELD_FLAGS.includes(a) || FIELD_FLAGS.some(f => a.startsWith(`${f}=`)) || /^-[fF]./.test(a)) fields = true
    }
    if (method !== null && WRITE_METHODS.includes(method)) return `gh api with method ${method}`
    if (fields && method !== 'GET') return 'gh api with field flags (a write)'
    return null
  }
  const writes = group === undefined ? undefined : GH_WRITES[group]
  if (writes === undefined) return null
  if (writes === '*' || (sub !== undefined && writes.includes(sub))) return `gh ${group}${writes === '*' ? '' : ` ${sub}`}`
  return null
}

// A push's parts: the remote (origin when none is named), its refspecs, and its flags.
type Push = { remote: string; refspecs: string[]; flags: string[] }

const PUSH_VALUED = ['-o', '--push-option', '--receive-pack', '--exec']
const PUSH_OK_FLAGS = ['-u', '--set-upstream', '-v', '--verbose', '-q', '--quiet', '--porcelain', '--progress', '--no-progress', '-n', '--dry-run', '--no-verify', '--verify', '--atomic']

function pushOf(args: readonly string[]): Push {
  const flags: string[] = []
  const rest: string[] = []
  let remote: string | null = null
  for (let i = 1; i < args.length; i++) {
    const a = args[i] ?? ''
    if (a.startsWith('--repo=')) remote = a.slice('--repo='.length)
    else if (a === '--repo') remote = args[++i] ?? ''
    else if (PUSH_VALUED.includes(a)) i++
    else if (/^-[a-zA-Z]{2,}$/.test(a)) flags.push(...[...a.slice(1)].map(ch => `-${ch}`))
    else if (a.startsWith('-')) flags.push(a)
    else rest.push(a)
  }
  if (remote === null) remote = rest.shift() ?? 'origin'
  return { remote, refspecs: rest, flags }
}

// pushRefusal: why a writer's push may not go ahead, or null. head is the slot's current branch
// (null: unknown), read only when the push names no refspec or pushes HEAD.
function pushRefusal(g: Guarded, p: Push, head: string | null): string | null {
  const force = p.flags.find(f => f === '-f' || f === '--force' || f.startsWith('--force-with-lease') || f === '--force-if-includes')
  if (force !== undefined) return `a force push (${force}) is refused: push your branch ${g.branch} without force`
  const other = p.flags.find(f => !PUSH_OK_FLAGS.includes(f))
  if (other !== undefined) return `git push ${other} is refused: push only your branch, as git push origin ${g.branch}`
  const specs = p.refspecs.length === 0 ? [null] : p.refspecs
  for (const spec of specs) {
    if (spec !== null && spec.startsWith('+')) return `a force push (${spec}) is refused: push your branch ${g.branch} without force`
    let dst = spec === null ? 'HEAD' : spec.includes(':') ? spec.slice(spec.indexOf(':') + 1) : spec
    if (spec !== null && spec.startsWith(':')) return `deleting a remote ref (${spec}) is refused`
    if (dst === 'HEAD') dst = head ?? 'HEAD'
    dst = dst.replace(/^refs\/heads\//, '')
    if (dst !== g.branch) return `a push to ${dst === 'HEAD' ? 'the current branch, which is not known' : dst} is refused: push only your branch, as git push origin ${g.branch}`
  }
  return null
}

// needsHead: whether a command's pushes need the slot's current branch to be judged.
export function needsHead(command: string): boolean {
  return simpleCommands(command).some(argv => {
    if (program(argv) !== 'git') return false
    const args = gitArgs(argv)
    if (args === null || args[0] !== 'push') return false
    const p = pushOf(args)
    return p.refspecs.length === 0 || p.refspecs.some(s => s === 'HEAD' || s.endsWith(':HEAD'))
  })
}

// The git branch options that read, delete or set an upstream rather than create a branch.
const BRANCH_READS = ['-l', '--list', '-a', '--all', '-r', '--remotes', '-v', '-vv', '--verbose', '--show-current', '--contains', '--no-contains', '--merged', '--no-merged', '--points-at', '--format', '--sort', '-d', '-D', '--delete', '-u', '--set-upstream-to', '--unset-upstream', '--edit-description', '--column', '--no-column', '--color', '--no-color']
const BRANCH_MAKES = ['-m', '-M', '-c', '-C', '--move', '--copy', '-f', '--force']

// branchMade: the branch command a writer may not run (creating, renaming or copying a branch, or
// a worktree), or null.
function branchMade(args: readonly string[]): string | null {
  const [sub, ...rest] = args
  if (sub === 'switch' && rest.some(a => ['-c', '-C', '--create', '--force-create', '--orphan'].includes(a) || /^--(force-)?create=/.test(a))) return 'git switch -c'
  if (sub === 'checkout' && rest.some(a => ['-b', '-B', '--orphan'].includes(a))) return 'git checkout -b'
  if (sub === 'branch') {
    if (rest.some(a => BRANCH_MAKES.includes(a))) return 'git branch -m/-c'
    const named = rest.some(a => !a.startsWith('-'))
    if (named && !rest.some(a => BRANCH_READS.includes(a) || BRANCH_READS.some(r => a.startsWith(`${r}=`)))) return 'git branch <name>'
  }
  if (sub === 'worktree' && rest[0] !== 'list') return `git worktree${rest[0] === undefined ? '' : ` ${rest[0]}`}`
  return null
}

// bashRefusal: the first rule a Bash command breaks, or null. head: the slot's current branch,
// which the hook reads when needsHead says a push needs it.
export function bashRefusal(g: Guarded, command: string, head: string | null = null): Refusal | null {
  for (const argv of simpleCommands(command)) {
    const name = program(argv)
    if (LOOP_TOOLS.includes(name)) return { cause: 'guard:command', reason: `${name} is not used by the factory loop's agents: the loop reviews, opens the PR and merges itself` }
    if (name === 'gh') {
      const write = ghWrite(argv)
      if (write !== null) return { cause: 'guard:command', reason: `${write} is refused: the factory loop owns GitHub writes (PRs, issues, labels, re-runs); say what you need in your answer instead` }
      continue
    }
    if (name !== 'git') continue
    const args = gitArgs(argv)
    if (args === null) continue
    if (args[0] === 'push') {
      const p = pushOf(args)
      if (g.role === 'reader') return { cause: 'guard:push', reason: 'git push is refused: this step reads only' }
      if (p.remote !== 'origin') return { cause: 'guard:push', reason: `a push to ${p.remote} is refused: push only to origin, as git push origin ${g.branch}` }
      const why = pushRefusal(g, p, head)
      if (why !== null) return { cause: 'guard:push', reason: why }
      continue
    }
    if (g.role === 'reader' && args[0] === 'commit') return { cause: 'guard:command', reason: 'git commit is refused: this step reads only' }
    if (g.role === 'writer') {
      const made = branchMade(args)
      if (made !== null) return { cause: 'guard:command', reason: `${made} is refused: work on your branch ${g.branch} in your slot ${g.slot}` }
    }
  }
  return null
}

// backgroundRefusal: any call in the background, Bash or Agent, so an agent neither ends its turn
// while work it started still runs (failures/F13) nor sits polling for it (R4-O4); a command runs
// in the foreground under its 10-minute timeout (10.5).
export function backgroundRefusal(tool: string, input: { run_in_background?: unknown }): Refusal | null {
  if (input.run_in_background !== true) return null
  return { cause: 'guard:command', reason: `${tool} in the background is refused: run it in the foreground and wait for it, a command with a timeout of up to 600000 ms` }
}

// agentRefusal: an Agent call with an isolation: `remote` always runs in the background, and
// `worktree` makes a git worktree, which a writer may not.
export function agentRefusal(input: { isolation?: unknown }): Refusal | null {
  if (input.isolation === undefined || input.isolation === null) return null
  return { cause: 'guard:command', reason: `an Agent call with isolation ${JSON.stringify(input.isolation)} is refused: leave isolation out, run it in the foreground in your own folder and wait for its answer` }
}

files.hooks/marker.ts:
// The spawn's slot line and the slot's step marker (docs/factory-loop/v2/SPEC.md 10.2, 10.3),
// pure. The loop's prompt opens with `factory-slot: <absolute slot path>`; factory-slot prepare
// wrote the marker `factory-step.json` into that slot's git dir. The companion starts the agent
// there only when the two agree with the spawn: the marker's issue, seq and step are the ones the
// agent's name carries (`<step>-<N>-s<seq>-a<attempt>`, D-11), and its type is the loop's.
import { normalize } from './guard'
import type { Role } from './guard'
import { scratchOk } from './scratch'

export const MARKER_FILE = 'factory-step.json'
const STEPS = ['design', 'build', 'review', 'fix', 'triage'] as const
export type Step = (typeof STEPS)[number]

// The marker as the loop writes it (plugins/factory-loop/hooks/v2/types.ts StepMarker).
export type Marker = {
  v: 1
  repo: string
  issue: number
  life: string
  seq: number
  step: Step
  role: Role
  branch: string
  // the issue's PR, null when it has none or the loop that wrote the marker did not say
  pr: number | null
  gateCommands: string[]
  gateTimeoutMs: number
  loopDir: string
  // the step attempt's scratch folder, under <loopDir>/scratch/; absent in an older marker, or when
  // the one it names is not a usable path
  scratch?: string
  // the stop gates the companion runs at once, and the longest a finished writer waits for its turn;
  // absent in an older marker, or when the value is not a whole number of at least 1: no limit, and
  // the default wait
  gateConcurrency?: number
  gateWaitTimeoutMs?: number
}

// slotLine: the slot the prompt's first line names, or null when it names none. The path must be
// absolute and plain (no `.` or `..` parts, no doubled or trailing `/`).
export function slotLine(prompt: string): string | null {
  const first = (prompt.split('\n', 1)[0] ?? '').replace(/\r$/, '')
  const m = /^factory-slot: (\/.*\S)\s*$/.exec(first)
  const path = m?.[1]
  if (path === undefined) return null
  return normalize(path, '/') === path ? path : null
}

const int = (v: unknown, min: number): v is number => typeof v === 'number' && Number.isInteger(v) && v >= min
const str = (v: unknown): v is string => typeof v === 'string' && v !== ''

// parseMarker: the marker file's text as a Marker; null when it does not read.
export function parseMarker(text: string | null): Marker | null {
  if (text === null) return null
  let o: Record<string, unknown>
  try {
    const v: unknown = JSON.parse(text)
    if (v === null || typeof v !== 'object' || Array.isArray(v)) return null
    o = v as Record<string, unknown>
  } catch {
    return null
  }
  if (o.v !== 1 || !str(o.repo) || !int(o.issue, 1) || !str(o.life) || !/^[0-9a-z]+$/.test(o.life) || !int(o.seq, 0)) return null
  if (!STEPS.includes(o.step as Step) || (o.role !== 'writer' && o.role !== 'reader') || !str(o.branch)) return null
  if (!Array.isArray(o.gateCommands) || !o.gateCommands.every(c => typeof c === 'string')) return null
  if (!int(o.gateTimeoutMs, 1) || !str(o.loopDir) || !o.loopDir.startsWith('/')) return null
  const loopDir = o.loopDir.replace(/\/+$/, '')
  return {
    v: 1,
    repo: o.repo,
    issue: o.issue,
    life: o.life,
    seq: o.seq,
    step: o.step as Step,
    role: o.role,
    branch: o.branch,
    pr: int(o.pr, 1) ? o.pr : null,
    gateCommands: (o.gateCommands as string[]).map(c => c.trim()).filter(c => c !== ''),
    gateTimeoutMs: o.gateTimeoutMs,
    loopDir,
    ...(scratchOk(o.scratch, loopDir) ? { scratch: o.scratch } : {}),
    ...(int(o.gateConcurrency, 1) ? { gateConcurrency: o.gateConcurrency } : {}),
    ...(int(o.gateWaitTimeoutMs, 1) ? { gateWaitTimeoutMs: o.gateWaitTimeoutMs } : {}),
  }
}

// nameParts: what the loop puts in an agent step's name (v2/steps.ts): `<step>-<N>-s<seq>-a<k>`.
export function nameParts(name: string | undefined): { step: string; issue: number; seq: number; attempt: number } | null {
  const m = /^([a-z]+)-(\d+)-s(\d+)-a(\d+)$/.exec(name ?? '')
  return m === null ? null : { step: m[1] ?? '', issue: Number(m[2]), seq: Number(m[3]), attempt: Number(m[4]) }
}

// mismatch: why the marker does not belong to this spawn, or null when it does.
export function mismatch(marker: Marker | null, spawn: { name?: string; subagentType: string }): string | null {
  if (marker === null) return `the slot has no readable step marker (${MARKER_FILE} in its git dir)`
  if (!spawn.subagentType.startsWith('factory-loop:')) return `${spawn.subagentType} is not one of the factory loop's agents`
  const n = nameParts(spawn.name)
  if (n === null) return `the agent's name ${spawn.name ?? '(none)'} does not say its step, issue and seq`
  if (n.issue !== marker.issue || n.seq !== marker.seq || n.step !== marker.step) {
    return `the slot is prepared for ${marker.step} of #${marker.issue} seq ${marker.seq}, not ${n.step} of #${n.issue} seq ${n.seq}`
  }
  return null
}

files.hooks/prompt.ts:
// Prompts nobody answers (docs/factory-loop/v2/SPEC.md 10.10), pure: the reason a refused call is
// given, and the note of the `prompt_denied` and `prompt_waiting` events, so the rules test covers
// them without the engine.
import { oneLine } from './gate'

// the most of a call's input a note carries (a Bash command, else the input as JSON)
export const INPUT_CLIP = 2000
const NONE = 'none'
const ME = 'factory-loop-workspace'

// enc: a value with no space in it: `%` and whitespace percent-encoded, as the loop's
// plugins/factory-loop/hooks/v2/events.ts enc does, so the loop's parsers read the note.
export function enc(v: string): string {
  return v.replace(/[%\s]/g, c => encodeURIComponent(c))
}

// clip: at most `max` characters.
export function clip(text: string, max = INPUT_CLIP): string {
  return text.length > max ? text.slice(0, max) : text
}

// What Claude Code's own check said (the result of `next(e)` for a tool.check).
export type Decided = { reason?: unknown; rule?: unknown; decider?: unknown }

const say = (v: unknown): string | null => {
  if (v === undefined || v === null || v === '') return null
  return typeof v === 'string' ? v : JSON.stringify(v)
}

// whyOf: Claude Code's reason, rule and decider as one line; null when it said none.
export function whyOf(d: Decided): string | null {
  const parts = [say(d.reason), say(d.rule) === null ? null : `rule ${say(d.rule)}`, say(d.decider) === null ? null : `decided by ${say(d.decider)}`]
  const text = parts.filter((p): p is string => p !== null).join('; ')
  return text === '' ? null : oneLine(text, 500)
}

// inputOf: what the note says of the call: a Bash command, else the input as JSON; clipped.
export function inputOf(tool: string, input: unknown): string {
  const command = tool === 'Bash' && input !== null && typeof input === 'object' ? (input as Record<string, unknown>).command : undefined
  if (typeof command === 'string') return clip(command)
  try {
    return clip(JSON.stringify(input) ?? '')
  } catch {
    return ''
  }
}

// a `rm` of a glob under a variable that is not guarded with `:?`: if the variable is empty it is
// `rm -f /*`. Group 1: the variable's name.
const VARIABLE_GLOB = /\$(?:\{([A-Za-z_]\w*)\}|([A-Za-z_]\w*))[^\s;|&]*[*?]/

// unguardedGlob: the variable of a Bash command that removes a glob under an unguarded variable;
// null for any other call.
export function unguardedGlob(tool: string, input: unknown): string | null {
  const command = inputOf(tool, input)
  if (tool !== 'Bash' || !/\brm\b/.test(command)) return null
  const m = VARIABLE_GLOB.exec(command)
  return m === null ? null : (m[1] ?? m[2] ?? null)
}

// rmHint: the safe rewrite, with the command's own variable.
export const rmHint = (name: string): string => `Never \`rm\` a glob under an unguarded variable: use \`"\${${name}:?}"/*\` or a literal path.`

// promptReason: what the agent is told when its call is refused, because Claude Code would have
// asked a person.
export function promptReason(tool: string, input: unknown, decided: Decided): string {
  const why = whyOf(decided)
  const glob = unguardedGlob(tool, input)
  return [
    `${ME}: this ${tool} call would wait on a person nobody watches, so it is refused.`,
    why === null ? null : `Claude Code's own reason: ${why}.`,
    glob === null ? null : rmHint(glob),
    'Find another way to do it or, failing that, end your step saying what you needed.',
  ]
    .filter((p): p is string => p !== null)
    .join(' ')
}

// The tokens of a prompt note, each `none` when unknown.
export type NoteFields = {
  life?: string | null
  seq?: number | null
  step?: string | null
  attempt?: number | null
  agent?: string | null
  agent_type?: string | null
  tool?: string | null
  slot?: string | null
  session?: string | null
  transcript?: string | null
  why?: string | null
  input?: string | null
}

// the order of the tokens: what identifies first, free text last
const NOTE_KEYS = ['life', 'seq', 'step', 'attempt', 'agent', 'agent_type', 'tool', 'slot', 'session', 'transcript', 'why', 'input'] as const

// promptNote: `key=value` tokens, a value encoded with no space in it, `none` for an unknown one
// (a string that is literally `none` has its first letter encoded, so it reads back as itself).
export function promptNote(f: NoteFields): string {
  return NOTE_KEYS.map(k => {
    const v = f[k]
    return `${k}=${v === undefined || v === null || v === '' ? NONE : v === NONE ? '%6Eone' : enc(String(v))}`
  }).join(' ')
}

// transcriptOf: an agent's own transcript, beside the session's:
// <session transcript without .jsonl>/subagents/agent-<id>.jsonl. null: the session's is not known.
export function transcriptOf(sessionTranscript: unknown, agentId: string): string | null {
  if (typeof sessionTranscript !== 'string' || sessionTranscript === '') return null
  return `${sessionTranscript.replace(/\.jsonl$/, '')}/subagents/agent-${agentId}.jsonl`
}

// the notification types that mean a prompt waits on a person
export const PROMPT_NOTIFICATIONS: readonly string[] = ['permission_prompt', 'worker_permission_prompt']

